import { injectable } from 'inversify';
import { IGetInitLoanProposalRepository } from '@src/domain/interfaces/loan_collateral/get_init_loan_proposal';
import { GetInitLoanProposalResponse } from '@src/domain/entities/loan_collateral/get_init_loan_proposal';
import { HttpService } from '@core/service';
import { BASE_URL_LOAN_API } from '@src/config';
import { GetInitLoanProposalPayload } from '@src/application/loan_collateral/queries/get_init_loan_proposal/get_init_loan_proposal_query';
import uuid from 'react-native-uuid';
import { commonService } from '@src/infrastructure/network/networkService';

@injectable()
export class GetInitLoanProposalRepository extends HttpService implements IGetInitLoanProposalRepository {
    constructor() {
        super({ baseURL: BASE_URL_LOAN_API });
    }
    async getInitLoanProposal(query: GetInitLoanProposalPayload): Promise<GetInitLoanProposalResponse> {
        const request = query as unknown as GetInitLoanProposalPayload;
        const url = '/getInitLoanProposal';
        const dataReq = {
            requestId: uuid.v4(),
            channel: String(request.channel),
            ipRequest: String(request.ipRequest),
            language: String(request.language),
            deviceInfo: {
                deviceId: String(request.deviceInfo.deviceId),
                deviceName: String(request.deviceInfo.deviceName),
                os: String(request.deviceInfo.os),
                osVersion: String(request.deviceInfo.osVersion),
            },
            data: {
                clientNo: String(request.data.clientNo),
                userId: String(request.data.userId),
                depositAccounts: request.data.depositAccounts,
            },
        };

        const { data } = await this.post(url, dataReq, {
            headers: commonService.getHeader({ 'X-CHANNEL': 'mfe-loan-collateral' }),
        });
        // console.log('\x1b[36m response get init loan proposal', data);
        return data as GetInitLoanProposalResponse;
    }
}
