import { TYPES } from '@src/di/types/types';
import { inject } from 'inversify';
import type { IInitLoanProposalRepository } from '@src/domain/interfaces/loan_collateral/init_loan_proposal';
import { InitLoanProposalPayload } from './init_loan_proposal_query';

export class InitLoanProposalHandler {
    private readonly _initLoanProposalRepository: IInitLoanProposalRepository;

    constructor(@inject(TYPES.IInitLoanProposalRepository) initLoanProposalRepository: IInitLoanProposalRepository) {
        this._initLoanProposalRepository = initLoanProposalRepository;
    }

    handle(dataReq: InitLoanProposalPayload) {
        return this._initLoanProposalRepository.initLoanProposal(dataReq);
    }
}
