import { createSlice } from '@reduxjs/toolkit';
import { confirmLoanRegister, fetchClientInfo, fetchCmsLoanRegisterConfig, fetchCmsLoanRegisterTnC, fetchCmsRegisterStaticData } from './thunk';
import { ClientInfo } from '@src/domain/entities/common/clientInfo';
import { loanRegister } from '../RegisterConfirmType';
import { Attributes as RegisterStaticData, CmsRegisterStaticData, registerStaticData } from '@src/domain/entities/cms/loan_register/registerStaticData';
import { DataLoanDemand, LoanDemandResponse } from '@src/domain/entities/loan_register/loanDemand';
import { CmsLoanRegisterConfig } from '@src/domain/entities/cms/loan_register/loanRegisterConfig';
import { CmsLoanRegisterTnC, LoanRegisterTncData } from '@src/domain/entities/cms/loan_register/loanRegisterTnC';
import { IBranch } from '@src/presentation/loan_collateral/collateral_confirm/type';

interface loanRegisterDataState {
    clientInfo?: ClientInfo;
    loanRegister?: loanRegister;
    cmsStaticData?: CmsRegisterStaticData;
    cmsStaticLoanPurpose?: CmsRegisterStaticData['data'];
    cmsStaticLoanMethod?: CmsRegisterStaticData['data'];
    cmsStaticLoanCollateral?: CmsRegisterStaticData['data'];
    cmsStaticLoanGender?: CmsRegisterStaticData['data'];
    loanDemandData: DataLoanDemand;
    loanDemandResponse?: LoanDemandResponse;
    cmsLoanRegisterConfig?: CmsLoanRegisterConfig;
    cmsLoanRegisterTnC?: LoanRegisterTncData;
    branchSelected?: IBranch;
    loanPurposeSelected?: RegisterStaticData;
    loanMethodSelected?: RegisterStaticData;
    loanCollateralSelected?: RegisterStaticData;
    loanGenderSelected?: RegisterStaticData;
    flowRegister?: string;
}
interface LoanRegisterState {
    data: loanRegisterDataState;
    status: 'idle' | 'loading' | 'succeeded' | 'failed';
    error: string | null;
    queue: Record<string, string>;
}

const initialState: LoanRegisterState = {
    data: {
        loanDemandData: { clientNo: '', consultantId: '', emailAddress: '' } as DataLoanDemand,
        loanDemandResponse: {} as LoanDemandResponse
    },
    status: 'idle',
    error: null,
    queue: {},
};

export const LoanRegisterSlice = createSlice({
    name: 'loanRegister',
    initialState,
    reducers: {
        resetLoanRegister: (state) => {
            state.data = { loanDemandData: {} as DataLoanDemand, loanDemandResponse: {} as LoanDemandResponse };
            state.error = null;
            state.status = 'idle';
        },
        selectCmsStaticLoanPurpose: (state, action) => {
            state.data.loanDemandData = handleUpdateLoanDemand(state.data.loanDemandData, { loanPurpose: action.payload.attributes.content });
            const list = handleSelect(state.data.cmsStaticLoanPurpose, action.payload, 'radio');
            state.data.cmsStaticLoanPurpose = list;
        },
        selectCmsStaticLoanMethod: (state, action) => {
            state.data.loanDemandData = handleUpdateLoanDemand(state.data.loanDemandData, { loanMethod: action.payload.attributes.content });
            const list = handleSelect(state.data.cmsStaticLoanMethod, action.payload, 'radio');
            state.data.cmsStaticLoanMethod = list;
        },
        selectCmsStaticLoanCollateral: (state, action) => {
            state.data.loanDemandData = handleUpdateLoanDemand(state.data.loanDemandData, { collateral: action.payload.attributes.content });
            const list = handleSelect(state.data.cmsStaticLoanCollateral, action.payload, 'radio');
            state.data.cmsStaticLoanCollateral = list;
        },
        selectCmsStaticLoanGender: (state, action) => {
            console.log('\x1b[31m handleUpdateLoanDemand', JSON.stringify(action.payload, null, 4));
            state.data.loanDemandData = handleUpdateLoanDemand(state.data.loanDemandData, { sex: action.payload.attributes.code });
            const list = handleSelect(state.data.cmsStaticLoanGender, action.payload, 'radio');
            state.data.cmsStaticLoanGender = list;
        },
        updateLoanDemandData: (state, action) => {
            // state.data.loanDemandData = {
            //     ...state.data.loanDemandData,
            //     ...action.payload
            // }
            state.data.loanDemandData = handleUpdateLoanDemand(state.data.loanDemandData, action.payload);
        },
        selectBranch: (state, action) => {
            console.log('\x1b[31m', 'selectBranch', action.payload);
            state.data.loanDemandData = handleUpdateLoanDemand(state.data.loanDemandData, { branchId: action.payload.branchId });
            state.data.branchSelected = action.payload;
        },
        updateFlowRegister: (state, action) => {
            state.data.flowRegister = action.payload;
        }
    },
    extraReducers: (builder) => {
        builder
            .addCase(confirmLoanRegister.pending, (state) => {
                state.status = 'loading';
                state.queue.cfr = 'confirmLoanRegister';
                state.error = null;
            })
            .addCase(confirmLoanRegister.rejected, (state, action) => {
                delete state.queue.cfr;
                if (Object.keys(state.queue).length === 0) {
                    state.status = 'failed';
                }
                state.error = action.error.message ?? 'Failed to register loan demand';
            })
            .addCase(confirmLoanRegister.fulfilled, (state, action) => {
                delete state.queue.cfr;
                if (Object.keys(state.queue).length === 0) {
                    state.status = 'succeeded';
                }
                // console.log('\x1b[36m', 'confirmLoanRegister => fulfilled', action.payload);
                // console.log('\x1b[36m', 'confirmLoanRegister => fulfilled', action.payload);
                if (action.payload.resultCode === '00') {
                    state.data.loanDemandResponse = action.payload;

                } else {
                    state.error = 'Failed to register loan demand';
                }

            })
            .addCase(fetchClientInfo.pending, (state) => {
                state.status = 'loading';
                state.queue.fci = 'fetchClientInfo';
                state.error = null;
            })
            .addCase(fetchClientInfo.rejected, (state, action) => {
                delete state.queue.fci;
                if (Object.keys(state.queue).length === 0) {
                    state.status = 'failed';
                }
                state.error = action.error.message ?? 'Failed to get client info';
            })
            .addCase(fetchClientInfo.fulfilled, (state, action) => {
                delete state.queue.fci;
                if (Object.keys(state.queue).length === 0) {
                    state.status = 'succeeded';
                }
                if (action.payload.data !== null) {
                    state.data.clientInfo = action.payload;
                    state.data.cmsStaticLoanGender?.find((item) => {
                        if (item.attributes.code === action?.payload?.data?.sex) {
                            item.attributes.selected = true;
                        }
                    });
                    let addressSection = action?.payload?.data?.location?.fullAddress?.split?.(',');
                    state.data.loanDemandData = handleUpdateLoanDemand(state.data.loanDemandData, {
                        globalId: action?.payload?.data?.globalId || "",
                        phoneNumber: action?.payload?.data?.phoneNumber || "",
                        emailAddress: action?.payload?.data?.emailAddress || "",
                        sex: action?.payload?.data?.sex || "",
                        address: action?.payload?.data?.location?.fullAddress || "",
                        clientNo: action?.payload?.data?.clientNo || "",
                        clientName: action?.payload?.data?.clientName || "",
                        birthDate: action?.payload?.data?.birthDate || "",
                        consultantId: '',
                        provinceId: action?.payload?.data?.location?.provinceId || "",
                        districtId: action?.payload?.data?.location?.districtId || "",
                        wardId: action?.payload?.data?.location?.wardId || "",
                        provinceName: addressSection?.[3] || "",
                        districtName: addressSection?.[2] || "",
                        wardName: addressSection?.[1] || ""
                    });
                }
                if (action?.payload?.resultCode !== '00') {
                    state.error = action?.payload?.resultMessage || 'Failed to get client info';
                }
            })
            .addCase(fetchCmsRegisterStaticData.pending, (state) => {
                state.status = 'loading';
                state.queue.fcrsd = 'fetchCmsRegisterStaticData';
                state.error = null;
            })
            .addCase(fetchCmsRegisterStaticData.rejected, (state, action) => {
                delete state.queue.fcrsd;
                if (Object.keys(state.queue).length === 0) {
                    state.status = 'failed';
                }
                // console.log('\x1b[31m', 'fetchCmsRegisterStaticData => rejected');
                // state.error = action.error.message ?? 'Failed to fetch loan register';
            })
            .addCase(fetchCmsRegisterStaticData.fulfilled, (state, action) => {
                delete state.queue.fcrsd;
                if (Object.keys(state.queue).length === 0) {
                    state.status = 'succeeded';
                }
                // console.log('\x1b[31m', 'fetchCmsRegisterStaticData => fulfilled', action.payload, state.queue, '' + Object.keys(state.queue).length);
                // console.log('\x1b[31m', 'fetchCmsRegisterStaticData => fulfilled', action.payload, state.queue, '' + Object.keys(state.queue).length);
                if (action.payload !== null) {
                    state.data.cmsStaticData = action.payload;
                    state.data.cmsStaticLoanPurpose = action.payload.data.filter((item: registerStaticData) => {
                        if (item.attributes.is_default && item.attributes.type === 'Purpose') {
                            state.data.loanDemandData = handleUpdateLoanDemand(state.data.loanDemandData, { loanPurpose: item.attributes.content });
                            item.attributes.selected = true;
                        }
                        return item.attributes.type === 'Purpose';
                    });
                    state.data.cmsStaticLoanCollateral = action.payload.data.filter((item: registerStaticData) => {
                        if (item.attributes.is_default && item.attributes.type === 'Collateral') {
                            state.data.loanDemandData = handleUpdateLoanDemand(state.data.loanDemandData, { collateral: item.attributes.content });
                            item.attributes.selected = true;
                        }
                        return item.attributes.type === 'Collateral';
                    });
                    state.data.cmsStaticLoanMethod = action.payload.data.filter((item: registerStaticData) => {
                        if (item.attributes.is_default && item.attributes.type === 'LoanMethod') {
                            state.data.loanDemandData = handleUpdateLoanDemand(state.data.loanDemandData, { loanMethod: item.attributes.content });
                            item.attributes.selected = true;
                        }
                        return item.attributes.type === 'LoanMethod';
                    });
                    state.data.cmsStaticLoanGender = action.payload.data.filter((item: registerStaticData) => {
                        // console.log('\x1b[31m', 'fetchCmsRegisterStaticData => fulfilled', item);s
                        if (item.attributes.is_default && item.attributes.type === 'Gender') {
                            state.data.loanDemandData = handleUpdateLoanDemand(state.data.loanDemandData, { sex: item.attributes.content });
                            item.attributes.selected = true;
                        }
                        return item.attributes.type === 'Gender';
                    });
                    action.payload.data.find((item: registerStaticData) => {
                        if (item.attributes.type === 'PaymentMethod') {
                            state.data.loanDemandData = handleUpdateLoanDemand(state.data.loanDemandData, { repaymentMethod: item.attributes.content });
                        }
                    });
                }
            })
            .addCase(fetchCmsLoanRegisterConfig.pending, (state) => {
                state.status = 'loading';
                state.queue.fclrc = 'fetchCmsLoanRegisterConfig';
                state.error = null;
            })
            .addCase(fetchCmsLoanRegisterConfig.rejected, (state, action) => {
                delete state.queue.fclrc;
                if (Object.keys(state.queue).length === 0) {
                    state.status = 'failed';
                }
                // state.error = action.error.message ?? 'Failed to fetch register config';
            })
            .addCase(fetchCmsLoanRegisterConfig.fulfilled, (state, action) => {
                delete state.queue.fclrc;
                if (Object.keys(state.queue).length === 0) {
                    state.status = 'succeeded';
                }
                // console.log('\x1b[31m', 'fetchCmsLoanRegisterConfig => fulfilled', action.payload);
                if (action.payload !== null) {
                    state.data.cmsLoanRegisterConfig = action.payload;
                    state.data.loanDemandData = handleUpdateLoanDemand(state.data.loanDemandData, {
                        loanAmount: action?.payload?.data?.attributes?.DL_LoanRegister_LoanLimit?.[0]?.loan_limit_default || '',
                        expectedInterestRate: ((action?.payload?.data?.attributes?.DL_LoanRegister_InterestRate?.[0]?.rate_value || 0) * 100) + '',
                        loanTerm: action?.payload?.data?.attributes?.DL_LoanRegister_LoanTerm?.[0]?.loan_term_default || '',
                    });
                }
            })
            .addCase(fetchCmsLoanRegisterTnC.pending, (state) => {
                state.status = 'loading';
                state.queue.fclrtnc = 'fetchCmsLoanRegisterTnC';
                state.error = null;
            })
            .addCase(fetchCmsLoanRegisterTnC.rejected, (state, action) => {
                delete state.queue.fclrtnc;
                if (Object.keys(state.queue).length === 0) {
                    state.status = 'failed';
                }
                // state.error = action.error.message ?? 'Failed to fetch register tnc';
            })
            .addCase(fetchCmsLoanRegisterTnC.fulfilled, (state, action) => {
                delete state.queue.fclrtnc;
                if (Object.keys(state.queue).length === 0) {
                    state.status = 'succeeded';
                }
                // console.log('\x1b[31m', 'fetchCmsLoanRegisterTnC => fulfilled', action.payload);
                if (action.payload !== null) {
                    state.data.cmsLoanRegisterTnC = action?.payload?.data?.find?.((item) => item?.attributes?.tnc_key === '01');
                }
            });
    },
});

const handleSelect = <T1>(list: T1, selected: any, type?: string) => {
    const currentSelect = Array.isArray(list)
        ? list.find((item) => item.attributes.type === selected.attributes.type && item.attributes.selected === true)
        : undefined;
    if (type === 'radio' && (currentSelect?.attributes?.code === selected?.attributes?.code)) {
        return list;
    }
    if (currentSelect) currentSelect.attributes.selected = false;
    const selectItem = Array.isArray(list) ? list.find((item) => item.id === selected.id) : undefined;
    if (selectItem) {
        if (selectItem.id === currentSelect?.id) {
            selectItem.attributes.selected = false;
        } else {
            selectItem.attributes.selected = true;
        }
    }
    // console.log('\x1b[31m', 'handleSelect', JSON.stringify({ currentSelect, selectItem, list }, null, 4));
    return list;
};

const handleUpdateLoanDemand = (loanDemand: DataLoanDemand, payload: Record<string, string | number>) => {
    return {
        ...loanDemand,
        ...payload,
    };
};
