interface ContentBottomSheetProps {
    onSubmit: (value: Record<string, string>) => void;
    clientName?: string;
    birthDay?: string;
}
const ContentBottomSheet = (props: ContentBottomSheetProps) => {
    const [name, setName] = useState<string>('');
    const [dob, setDob] = useState<string>('');
    const { t } = useTranslation(['module_register']);
    const { onSubmit } = props;
    const [executeValidate, setExecuteValidate] = useState<boolean>(false);

    const inputDob = [
        { id: 1, title: `${t('screen_confirm.customer_info.dob')}`, fn: () => { }, divider: true },
    ] as DataSelectList[];

    const handleSubmit = () => {
        setExecuteValidate(true);
        if (!name || !dob) return;
        console.log('\x1b[31m submit', name, dob);
        onSubmit?.({ birthDate: dob || props.birthDay || '', clientName: name || props.clientName || '' });
        Keyboard.dismiss();
    }
    useEffect(() => {
        console.log('\x1b[31m nameeeeee', name)
        setDob(props.birthDay || '');
        setName(props.clientName || '');
    }, [props.birthDay, props.clientName])
    return (
        <View>
            <ContentInput label={t('screen_confirm.customer_info.label_input_name')} onChange={(value) => { console.log('\x1b[31m onchange nef', value); setName(value) }} autoFocus={true} value={props.clientName} validate={validator.validateFullName} maxLength={50} executeValidate={executeValidate} validated={setExecuteValidate} />
            <ContentInput label={`${t('screen_confirm.customer_info.dob')}`} inputType='numeric' formatInput='date' onChange={setDob} value={props.birthDay} validate={validator.validateBirthDate} maxLength={10} executeValidate={executeValidate} validated={setExecuteValidate} />
            <Spacer height={40} />
            <GradientButton gradientProps={{ type: 'primary' }} title='Lưu' onPress={handleSubmit} />
            <Spacer height={16} />
        </View>
    )
}

interface contentInputProps {
    value?: string;
    placeholder?: string;
    label?: string;
    validate?: (value: string) => ValidationResult;
    onChange?: (value: string) => void;
    textProps?: TextInputProps;
    inputType?: string;
    formatInput?: string;
    autoFocus?: boolean;
    maxLength?: number;
    executeValidate?: boolean;
    validated?: (value: boolean) => void;
}
interface ExtendTextInput extends TextInput, MaterialTextInputPropsMethod { }
const ContentInput = (Props: contentInputProps) => {
    const { placeholder, label, validate, textProps, inputType, formatInput, onChange, autoFocus, maxLength, executeValidate, validated } = Props;
    const { theme } = useTheme();
    const { t } = useTranslation(['validator']);

    const [displayValue, setDisplayValue] = useState('');
    const [format, setFormat] = useState<string>('');
    const [errorMessages, setErrorMessages] = useState<string>('');
    const inputRef = useRef<ExtendTextInput | null>(null);
    let regexDate = /^[0-9]{0,2}\/[0-9]{0,2}\/[0-9]{0,4}$/g;
    const formatDate = (input: string) => {
        console.log('input', input);
        let day = '';
        let month = '';
        let year = '';
        let currentYear = new Date().getFullYear() + '';
        if (regexDate.test(input)) {
            let splitDate = input.split('/');
            input = +splitDate[0] > 31 ? input.replace(splitDate[0], '31') : input;
            input = +splitDate[1] > 12 ? input.replace(splitDate[1], '12') : input;
            input =
                +splitDate[2] > +currentYear
                    ? input.replace(splitDate[2], currentYear)
                    : input;
            setDisplayValue(input);
            onChange?.(input);
            return;
        }
        input = input.replace(/[^\d/]/g, '');

        let dateLength = input.length;
        console.log('\x1b[31m input', input, dateLength);
        if (dateLength === 0) {
            setDisplayValue(' ');
            return;
        }
        console.log('\x1b[31m input', input, dateLength);
        // console.log(dateLength, displayValue.length);
        let isDelete = dateLength < displayValue.length;
        if (dateLength > 10) return;
        let [fDay, fMonth, fYear] = format.split('/');
        fDay = fDay || '';
        fMonth = fMonth || '';
        fYear = fYear || '';
        // console.log('\x1b[31m input', input);

        switch (dateLength) {
            case 1:
                console.log('lenght 1', input);
                if (isDelete && input === '0') {
                    day = '';
                    break;
                }
                fDay = input === '0' ? '0D/' : 'DD/';
                setFormat(fDay);
                if (input === '0') {
                    day = input;
                    break;
                }
                // day = String(input).padStart(2, '0');
                day = input;
                break;
            case 2:
                console.log('lenght 2', input);
                // console.log('2', input);
                let tempDay = input.replace('/', '');
                if (isDelete) {
                    +tempDay[0] === 0 ? (day = '0') : (day = tempDay.substring(0, 1));
                    break;
                }
                if (+input > 31) {
                    day = `03/`;
                    +input[1] > 1 ? (month = `0${input[1]}/`) : (month = `${input[1]}`);
                    break;
                }
                day = `${tempDay}/`;
                break;
            case 3:
            case 4:
                console.log('lenght 3 4', input, isDelete);
                day = input.replace('/', '');
                console.log(day);
                if (isDelete) {
                    day = `${day.substring(0, 2)}/`;
                    month = '';
                    break;
                }
                // console.log('len4 day', day);
                fMonth = day[2] === '0' ? '0M/' : 'MM/';
                setFormat(fDay + '/' + fMonth);
                if (day[0] === '0') {
                    if (+day.substring(0, 2) >= 3 && +day.substring(2) > 1) {
                        month = `0${day.substring(2)}/`;
                        day = `${day.substring(0, 2)}/`;
                        break;
                    }
                    if (fDay[0] === '0' && day[1] !== '0') {
                        if (day.substring(2) === '0') {
                            month = '0';
                        } else {
                            month = `0${day.substring(2)}`;
                        }
                        day = String(+day.substring(0, 2)).padStart(2, '0') + '/';
                        break;
                    }
                    day = String(+day).padStart(2, '0') + '/';
                } else {
                    +day.substring(2) > 1
                        ? (month = `0${day.substring(2)}/`)
                        : (month = `${day.substring(2)}`);
                    day = `${day.substring(0, 2)}/`;
                }
                break;
            case 5:
            case 6:
                console.log('length 5 6', input);
                let tempDate = input.split('/');
                console.log(tempDate, isDelete);
                day = `${tempDate[0]}/`;
                if (tempDate[1][0] !== '0') {
                    if (isDelete && dateLength === 5) {
                        +tempDate[1][1] === 0
                            ? // month = String(+tempDate[1].substring(0, 1)).padStart(2, '0')
                            (month = '0')
                            : (month = `${tempDate[0][1]}`);
                        break;
                    }
                    if (+tempDate[1] > 12) {
                        month = '12/';
                        +tempDate[1][1] > +currentYear[0]
                            ? (year = currentYear[0])
                            : (year = `${tempDate[1][1]}`);
                        break;
                    }
                    month = `${tempDate[1]}/`;
                } else {
                    console.log(isDelete, dateLength, displayValue.length);
                    if (isDelete) {
                        dateLength === 6
                            ? (month = `${tempDate[1]}/`)
                            : //(month = `${String(+tempDate[1].substring(0, 1)).padStart(2,'0')}` );
                            (month = '0');
                        break;
                    }
                    console.log(tempDate[1]);
                    month = `${String(+tempDate[1]).padStart(2, '0')}/`;
                    if (+month.substring(0, 2) > 12) {
                        month = '12/';
                    }
                }
                break;
            case 7:
                console.log('lenght 7', input);
                day = input.substring(0, 3);
                month = input.substring(3).replace('/', '');

                if (month[0] === '0') {
                    if (+month.substring(0, 2) > 1) {
                        year = `${month.substring(2)}`;
                        month = `${month.substring(0, 2)}/`;
                        if (+year[0] > +currentYear[0]) {
                            year = currentYear[0];
                        }
                        break;
                    }
                    if (fMonth[0] === '0' && month[1] !== '0') {
                        year = `${month.substring(2)}`;
                        month = String(+month.substring(0, 2)).padStart(2, '0') + '/';
                        break;
                    }
                    month = String(+month).padStart(2, '0') + '/';
                    if (+month.substring(0, 2) > 12) {
                        month = '12/';
                    }
                } else {
                    year = `${month.substring(2)}`;
                    month = `${month.substring(0, 2)}/`;
                    if (+year[0] > +currentYear[0]) {
                        year = currentYear[0];
                    }
                }
                break;
            default:
                let date = input.split('/');
                // console.log(date);
                day = date[0] ? `${date[0]}/` : '';
                month = date[1] ? `${date[1]}/` : '';
                year = date[2] || '';
                if (+year[0] >= +currentYear[0]) {
                    for (let i = 1; i < 4; i++) {
                        if (+year[i] > +currentYear[i]) {
                            year =
                                year.substring(0, i) + currentYear[i] + year.substring(i + 1);
                        }
                    }
                }
                break;
        }

        // console.log(day, month, year);
        let formatted = day + month + year;
        console.log('\x1b[31m formatted', day, month, year, formatted);
        setDisplayValue(formatted);
        onChange?.(formatted);
    }
    const handleValidate = (value: string) => {
        const validation = validate?.(value);
        validated?.(false)
        console.log('\x1b[31m validation', validation);
        if (validation?.isEmpty) {
            setErrorMessages(validation.errors || '');
            return false;
        }
        if (validation?.isInvalid) {
            console.log('\x1b[31m validation.errors', validation.errors);
            setErrorMessages(validation?.errors || '');
            return false;
        }
        setErrorMessages('');
        return true;
    };
    const handleInput = (text: string) => {
        let value = ''
        setErrorMessages('')
        // handleValidate(text);
        switch (formatInput) {
            case 'date':
                formatDate(text);
                break;
            default:
                console.log('\x1b[31m text', text);
                setDisplayValue(text);
                onChange?.(text);
                break;
        }
    }
    useEffect(() => {
        setDisplayValue(Props.value || '');
        // handleValidate(Props.value || '');
        if (Props.value) {
            setErrorMessages('')
        }
    }, [Props.value]);
    useEffect(() => {
        if (autoFocus) {
            setTimeout(() => {
                if (inputRef) {
                    inputRef?.current?.focus();
                }
            }, 350);
        }
    }, [autoFocus])

    useEffect(() => {
        console.log('\x1b[31m displayValue', displayValue);
        if (executeValidate) {
            handleValidate(displayValue);
        }
    }, [executeValidate, errorMessages])

    return (
        <View >
            <MaterialTextInput
                ref={inputRef}
                label={label}
                placeholder={placeholder}
                // keyboardType={inputType}
                value={displayValue}
                // defaultValue={displayValue}
                onChangeText={(text) => { handleInput(text); }}
                autoFocus={false}
                inputMode={inputType as InputModeOptions || 'text'}
                inputStyle={{ ...theme.Typography.TextBody.Regular } as TextStyle}
                textLabelStyle={{ color: 'red' } as TextStyle}
                maxLength={maxLength}

            />
            <Text style={{ ...theme.Typography.TextCaption100.Regular, color: theme.Colors.Text.Error }}>{t(`${errorMessages}`)}</Text>
        </View>
    )
}

export default BottomSheetInputNameAndDob;
